type PlaceOrder = {
  requestKey: string;
  shopperId: string; // supplied by trusted authentication context
  lines: Array<{ sku: string; quantity: number }>;
};

// Illustrative pseudocode: error handling and reconciliation omitted.
async function placeOrder(command: PlaceOrder): Promise<Order> {
  const prior = await orders.findByRequestKey(command.requestKey);
  if (prior) return prior;
  const reservation = await inventory.reserve(command);
  const authorization = await payments.authorize(command, reservation);
  const order = Order.accept(command, reservation, authorization);
  await orders.saveWithEvent(order, order.acceptedEvent());
  return order;
}
